$ErrorActionPreference='Stop';Set-Location $PSScriptRoot;$port=8080;if(Test-Path .env){$line=Get-Content .env|Where-Object{$_ -match '^ATLAS_PORT='}|Select-Object -Last 1;if($line){$port=[int]($line -replace '^ATLAS_PORT=','')}};$h=Invoke-RestMethod "http://127.0.0.1:$port/api/health";if(-not$h.ok){throw 'Health failed'};$s=Invoke-RestMethod "http://127.0.0.1:$port/api/instruments";if(-not($s.symbol -contains 'EURUSD')){throw 'Instrument API failed'};Invoke-WebRequest "http://127.0.0.1:$port/"|Out-Null;Write-Host 'PASS: health, instruments, frontend HTTP.'
